## 🎭 3. Proxy Magic — Observable Objects

```js
const observe = (obj, onChange) =>
  new Proxy(obj, {
    set(target, key, value) {
      const prev = target[key];
      target[key] = value;
      onChange({ key, prev, next: value });
      return true;
    }
  });

const state = observe({ count: 0 }, diff =>
  console.log(`${diff.key}: ${diff.prev} → ${diff.next}`)
);

state.count++; // count: 0 → 1
state.count++; // count: 1 → 2
```

