## 🔮 4. Tagged Template Literals — Mini HTML Sanitizer

```js
const escape = str => str
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const html = (strings, ...values) =>
  strings.reduce((out, str, i) =>
    `${out}${str}${values[i] !== undefined ? escape(String(values[i])) : ''}`, '');

const userInput = '<script>alert("xss")</script>';
const safe = html`<div class="user">${userInput}</div>`;
// → <div class="user">&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;</div>
```

