## 🧩 6. Recursive `deepFreeze` — Immutable by Nature

```js
const deepFreeze = obj =>
  Object.keys(obj).reduce((frozen, key) => {
    if (typeof obj[key] === 'object' && obj[key] !== null)
      deepFreeze(obj[key]);
    return frozen;
  }, Object.freeze(obj));

const config = deepFreeze({
  api: { url: 'https://api.example.com', timeout: 3000 },
  features: { darkMode: true }
});

config.api.url = 'hacked'; // ❌ silently fails (or throws in strict mode)
console.log(config.api.url); // → 'https://api.example.com' ✅
```

