## 🎲 7. One-liner Wonders

```js
// Shuffle an array (Fisher-Yates in one chain)
const shuffle = arr => arr
  .map(v => [Math.random(), v])
  .sort(([a], [b]) => a - b)
  .map(([, v]) => v);

// Deep clone with structuredClone (modern & beautiful)
const clone = obj => structuredClone(obj);

// Group an array by a key
const groupBy = (arr, fn) =>
  arr.reduce((map, item) => ({
    ...map,
    [fn(item)]: [...(map[fn(item)] ?? []), item]
  }), {});

const grouped = groupBy(
  [{ type: 'fruit', name: '🍎' }, { type: 'veggie', name: '🥕' }, { type: 'fruit', name: '🍌' }],
  item => item.type
);
// → { fruit: [{...}, {...}], veggie: [{...}] }
```

